    }

    .hero-image,
    .product-image,
    .deal-image,
    .editorial-image {
        border: 1px solid CanvasText;
    }
}

/* Responsive design */
@media (max-width: 1024px) {
    .header-content {
        padding: var(--spacing-md);
        gap: var(--spacing-md);
    }

    .primary-nav ul {
        gap: var(--spacing-md);
    }

