    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 640px) {
    :root {
        font-size: 14px;
    }

    .header-content {
        padding: var(--spacing-sm);
    }

    .brand-name {
        display: none;
    }

    .primary-nav {
        display: none;
    }

    main {
