    }

    .hero {
        padding: var(--spacing-lg) 0;
    }

    .hero h1 {
        font-size: clamp(1.5rem, 3.5vw, 2rem);
    }

    .hero-content {
        gap: var(--spacing-sm);
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .product-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .promo-banner {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .promo-content h2 {
        font-size: 1.25rem;
    }

    .newsletter-section {
        padding: var(--spacing-lg);
    }

    .newsletter-section h2 {
        font-size: 1.5rem;
    }

    .newsletter-form {
        max-width: 100%;
    }

    .footer-content {
        grid-template-columns: repeat(2, 1fr);
        gap: var(--spacing-md);
    }

    .footer-bottom {
        gap: var(--spacing-sm);
    }

    .legal-links {
        flex-direction: column;
        gap: var(--spacing-sm);
    }
}
