    color: var(--color-accent-light);
}

/* Lists */
ul, ol {
    list-style: none;
}

/* Header */
header {
    background-color: var(--color-bg-secondary);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow-md);
}

.header-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-md) var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo-section {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    min-width: 0;
}

.logo {
    width: 32px;
    height: 32px;
    color: var(--color-accent);
    flex-shrink: 0;
}

.brand-name {
    font-size: 1.5rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    color: var(--color-text);
}

/* Primary Navigation */
.primary-nav ul {
    display: flex;
    gap: var(--spacing-lg);
}

.nav-link {
    color: var(--color-text-secondary);
    font-weight: 500;
    transition: color var(--transition-fast);
}

.nav-link:hover {
    color: var(--color-accent);
}

/* Header Actions */
.header-actions {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
}

.icon-button {
    background: none;
    border: none;
    color: var(--color-text);
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: color var(--transition-fast);
    border-radius: var(--radius-md);
}

.icon-button:hover {
    color: var(--color-accent);
}

.icon-button svg {
    width: 20px;
    height: 20px;
}

/* Main Content */
main {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* Hero Section */
.hero {
    padding: var(--spacing-2xl) 0;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-2xl);
    align-items: center;
}

.hero-content {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.hero h1 {
    font-size: clamp(2rem, 5vw, 3.5rem);
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--color-text-secondary);
    font-weight: 300;
}

.hero-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-border) 100%);
    border-radius: var(--radius-lg);
    border: 1px solid var(--color-border-light);
}

/* Buttons */
.btn {
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: var(--radius-md);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-base);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--spacing-xs);
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-bg);
}

.btn-primary:hover {
    background-color: var(--color-accent-light);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}

.btn-primary:active {
    transform: translateY(0);
}

.btn-outline {
    background-color: transparent;
    color: var(--color-accent);
    border: 1px solid var(--color-accent);
}

.btn-outline:hover {
    background-color: rgba(212, 175, 55, 0.1);
    color: var(--color-accent-light);
}

.btn-small {
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
}

.btn-dismiss {
    background: none;
    border: none;
    color: var(--color-text-secondary);
    font-size: 1.5rem;
    cursor: pointer;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: color var(--transition-fast);
}

.btn-dismiss:hover {
    color: var(--color-text);
}

/* Section Header */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: var(--spacing-xl);
    gap: var(--spacing-lg);
}

.section-header h2 {
    font-size: 2rem;
    font-weight: 700;
}

.view-all-link {
    color: var(--color-text-secondary);
    font-weight: 500;
    white-space: nowrap;
}

.view-all-link:hover {
    color: var(--color-accent);
}

/* Featured Products Section */
.featured-section {
    padding: var(--spacing-2xl) 0;
    border-top: 1px solid var(--color-border);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-md);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.product-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-lg);
}

.product-image-link {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    text-decoration: none;
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-border) 100%);
    border-radius: var(--radius-md);
    border: 1px solid var(--color-border-light);
}

.product-image-2 {
    background: linear-gradient(135deg, #1a1f3a 0%, #2a2f48 50%, #1a1f3a 100%);
}

.product-image-3 {
    background: linear-gradient(135deg, #2a2f48 0%, #1a1f3a 100%);
}

.product-image-4 {
    background: linear-gradient(135deg, #1f2a3a 0%, #2a3548 50%, #1f2a3a 100%);
}

.product-name {
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--color-text);
}

.product-price {
    color: var(--color-accent);
    font-weight: 600;
    font-size: 1.25rem;
}

/* Promo Banner */
.promo-banner {
    background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-light) 100%);
    color: var(--color-bg);
    padding: var(--spacing-lg);
    border-radius: var(--radius-lg);
    margin: var(--spacing-2xl) 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--spacing-lg);
}

.promo-content h2 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
}

.promo-content p {
    margin: var(--spacing-xs) 0;
    opacity: 0.95;
}

.promo-code {
    font-weight: 600;
}

/* Deals Section */
.deals-section {
    padding: var(--spacing-2xl) 0;
    border-top: 1px solid var(--color-border);
}

.deal-countdown {
    font-size: 0.875rem;
    color: var(--color-deal);
    font-weight: 600;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-md);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    position: relative;
}

.deal-card:hover {
    border-color: var(--color-deal);
    box-shadow: var(--shadow-lg);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-deal);
    color: var(--color-bg);
    padding: 0.25rem 0.75rem;
    border-radius: var(--radius-sm);
    font-weight: 700;
    font-size: 0.875rem;
}

.deal-image-link {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    text-decoration: none;
}

.deal-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-border) 100%);
    border-radius: var(--radius-md);
    border: 1px solid var(--color-border-light);
}

.deal-image-2 {
    background: linear-gradient(135deg, #2a2f48 0%, #1a1f3a 100%);
}

.deal-image-3 {
    background: linear-gradient(135deg, #1a1f3a 0%, #2a2f48 50%, #1a1f3a 100%);
}

.deal-name {
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--color-text);
}

.deal-pricing {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
}

.deal-price-original {
    color: var(--color-text-muted);
    text-decoration: line-through;
    font-size: 0.875rem;
}

.deal-price-current {
    color: var(--color-deal);
    font-weight: 700;
    font-size: 1.25rem;
}

/* Editorial Section */
.editorial-section {
    padding: var(--spacing-2xl) 0;
    border-top: 1px solid var(--color-border);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    background-color: var(--color-bg-secondary);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: all var(--transition-base);
}

.editorial-card:hover {
    border-color: var(--color-accent);
    box-shadow: var(--shadow-lg);
}

.editorial-link {
    display: flex;
    flex-direction: column;
    height: 100%;
    text-decoration: none;
    color: inherit;
}

.editorial-image {
    width: 100%;
    aspect-ratio: 16 / 9;
    background: linear-gradient(135deg, var(--color-bg-tertiary) 0%, var(--color-border) 100%);
    border-bottom: 1px solid var(--color-border-light);
}

.editorial-image-2 {
    background: linear-gradient(135deg, #2a2f48 0%, #1a1f3a 100%);
}

.editorial-image-3 {
    background: linear-gradient(135deg, #1f2a3a 0%, #2a3548 100%);
}

.editorial-content {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
    flex: 1;
}

.editorial-category {
    color: var(--color-accent);
    font-size: 0.875rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.editorial-title {
    font-size: 1.25rem;
    font-weight: 700;
    line-height: 1.3;
}

.editorial-excerpt {
    color: var(--color-text-secondary);
    font-size: 0.95rem;
    flex: 1;
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-bg-secondary) 0%, var(--color-bg-tertiary) 100%);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: var(--spacing-2xl);
    text-align: center;
    margin: var(--spacing-2xl) 0;
}

.newsletter-section h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-md);
}

.newsletter-section > p {
    color: var(--color-text-secondary);
    margin-bottom: var(--spacing-lg);
    font-size: 1.1rem;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    max-width: 400px;
    margin: 0 auto var(--spacing-lg);
}

.email-input {
    flex: 1;
    padding: 0.75rem var(--spacing-sm);
    background-color: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    color: var(--color-text);
    font-size: 1rem;
}

.email-input::placeholder {
    color: var(--color-text-muted);
}

.email-input:focus {
    border-color: var(--color-accent);
}

.newsletter-note {
    font-size: 0.875rem;
    color: var(--color-text-muted);
}

/* Footer */
footer {
    background-color: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
    margin-top: var(--spacing-2xl);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.footer-content {
    max-width: 1400px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-xl);
}

.footer-section h3 {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-md);
}

.footer-section ul {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-secondary);
    font-size: 0.95rem;
}

.footer-section a:hover {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    flex-direction: row;
    gap: var(--spacing-md);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-lg);
    color: var(--color-text-muted);
    font-size: 0.875rem;
}

.legal-links {
    display: flex;
    gap: var(--spacing-lg);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* High contrast mode */
@media (prefers-contrast: more) {
    :root {
        --color-accent: #ffd700;
        --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.6);
    }

    .product-card,
    .deal-card,
    .editorial-card {
        border-width: 2px;
    }
}

/* Forced colors mode */
@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card,
    .promo-banner {
        border: 1px solid CanvasText;
    }

    .btn-primary {
        background-color: CanvasText;
        color: Canvas;
    }

    .hero-image,
    .product-image,
    .deal-image,
    .editorial-image {
        border: 1px solid CanvasText;
    }
}

/* Responsive design */
@media (max-width: 1024px) {
    .header-content {
        padding: var(--spacing-md);
        gap: var(--spacing-md);
    }

    .primary-nav ul {
        gap: var(--spacing-md);
    }

    .hero {
        grid-template-columns: 1fr;
        padding: var(--spacing-xl) 0;
    }

    .hero h1 {
        font-size: clamp(1.75rem, 4vw, 2.5rem);
    }

    .hero-image {
        aspect-ratio: 1.2;
    }

    .promo-banner {
        flex-direction: column;
        text-align: center;
    }

    .section-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 640px) {
    :root {
        font-size: 14px;
    }

    .header-content {
        padding: var(--spacing-sm);
    }

    .brand-name {
        display: none;
    }

    .primary-nav {
        display: none;
    }

    main {
        padding: 0 var(--spacing-sm);
    }

    .hero {
        padding: var(--spacing-lg) 0;
    }

    .hero h1 {
        font-size: clamp(1.5rem, 3.5vw, 2rem);
    }

    .hero-content {
        gap: var(--spacing-sm);
    }

    .hero-subtitle {
        font-size: 1rem;
    }

    .section-header h2 {
        font-size: 1.5rem;
    }

    .product-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .promo-banner {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .promo-content h2 {
        font-size: 1.25rem;
    }

    .newsletter-section {
        padding: var(--spacing-lg);
    }

    .newsletter-section h2 {
        font-size: 1.5rem;
    }

    .newsletter-form {
        max-width: 100%;
    }

    .footer-content {
        grid-template-columns: repeat(2, 1fr);
        gap: var(--spacing-md);
    }

    .footer-bottom {
        gap: var(--spacing-sm);
    }

    .legal-links {
        flex-direction: column;
        gap: var(--spacing-sm);
    }
}

